// ListInput is the request shape every repository List takes: AIP page
// controls, an order_by string, and a raw AIP-160 filter expression.
type ListInput struct {
	PageSize  int32
	PageToken string
	OrderBy   string
	Filter    string
	// ShowDeleted includes soft-deleted records (AIP-164 show_deleted); it
	// has no effect on resources without soft delete.
	ShowDeleted bool
	// Where are typed conditions ANDed with Filter, for a service building a
	// query in code rather than passing a caller's filter through: a batched
	// read (filterx.In), or a strict bound AIP-160 text would also express.
	// Field names are the filter fields Filter accepts.
	Where []filterx.Condition
	// ReadMask names the fields to read (AIP-157 partial response); empty
	// reads every field. Each record comes back holding only those fields and
	// its name. A path into a message field ("start.date_time") reads the
	// whole field. Fields stored in other tables -- value objects, repeated
	// children -- are read only when named: on GraphQL each costs a query
	// per record, so a read of keys and timestamps costs one query per page.
	// On GORM the row's other columns are also left out of the SELECT.
	// Paths naming no field of the resource are rejected with
	// ErrInvalidArgument.
	ReadMask []string
}

// KeysPerRead bounds the keys one statement of ListByKeys names: past it an
// IN list costs the planner more than a second statement does, and engines
// cap a request's size. ReadParallelism bounds the statements in flight at
// once. Both are variables so a process can tune them; set them before use.
var (
	KeysPerRead     = 1000
	ReadParallelism = 4
)

// ListByKeys reads every record whose filter field field is one of keys, by
// way of list (a repository's List, across parents): the keys, duplicates
// dropped, in chunks of at most KeysPerRead, at most ReadParallelism chunks at
// once, each chunk paged to the end. in narrows every read (Filter, Where,
// ShowDeleted, ReadMask, OrderBy); its page fields are ignored. Records come
// back chunk by chunk in key order, each chunk in in.OrderBy order. The first
// error cancels the reads still running and is returned. field must be a
// text, enum or reference filter field (filterx.In).
func ListByKeys[T any](ctx context.Context, field string, keys []string, in ListInput, list func(ctx context.Context, in ListInput) ([]T, string, error)) ([]T, error) {
	seen := make(map[string]bool, len(keys))
	uniq := make([]string, 0, len(keys))
	for _, k := range keys {
		if !seen[k] {
			seen[k] = true
			uniq = append(uniq, k)
		}
	}
	if len(uniq) == 0 {
		return nil, nil
	}
	size, par := max(KeysPerRead, 1), max(ReadParallelism, 1)
	var chunks [][]string
	for i := 0; i < len(uniq); i += size {
		chunks = append(chunks, uniq[i:min(i+size, len(uniq))])
	}
	read := func(ctx context.Context, chunk []string) ([]T, error) {
		page := in
		page.PageSize, page.PageToken = 1000, ""
		page.Where = append(append(make([]filterx.Condition, 0, len(in.Where)+1), in.Where...), filterx.In(field, chunk...))
		var out []T
		for {
			rows, next, err := list(ctx, page)
			if err != nil {
				return nil, err
			}
			out = append(out, rows...)
			if next == "" {
				return out, nil
			}
			page.PageToken = next
		}
	}
	if len(chunks) == 1 {
		return read(ctx, chunks[0])
	}
	ctx, cancel := context.WithCancel(ctx)
	defer cancel()
	parts := make([][]T, len(chunks))
	errs := make([]error, len(chunks))
	sem := make(chan struct{}, par)
	var wg sync.WaitGroup
	for i, c := range chunks {
		wg.Add(1)
		sem <- struct{}{}
		go func() {
			defer wg.Done()
			defer func() { <-sem }()
			if parts[i], errs[i] = read(ctx, c); errs[i] != nil {
				cancel()
			}
		}()
	}
	wg.Wait()
	var out []T
	for i := range chunks {
		if errs[i] != nil && !errors.Is(errs[i], context.Canceled) {
			return nil, errs[i]
		}
	}
	for i := range chunks {
		if errs[i] != nil {
			return nil, errs[i]
		}
		out = append(out, parts[i]...)
	}
	return out, nil
}

// CheckReadMask rejects a read mask naming a field m does not have.
func CheckReadMask(m proto.Message, mask []string) error {
	fields := m.ProtoReflect().Descriptor().Fields()
	for _, p := range mask {
		top, _, _ := strings.Cut(p, ".")
		if fields.ByName(protoreflect.Name(top)) == nil {
			return fmt.Errorf("%w: read_mask names %q, which %s does not have", ErrInvalidArgument, p, m.ProtoReflect().Descriptor().Name())
		}
	}
	return nil
}

// Reads reports whether a read under mask reads field: an empty mask reads
// everything, otherwise a path naming the field or a path inside it.
func Reads(mask []string, field string) bool { return GroupTouched(mask, field) }

// Narrow clears every field of m that mask does not read, keeping its name. An
// empty mask keeps everything.
func Narrow(m proto.Message, mask []string) {
	if len(mask) == 0 {
		return
	}
	r := m.ProtoReflect()
	var drop []protoreflect.FieldDescriptor
	r.Range(func(fd protoreflect.FieldDescriptor, _ protoreflect.Value) bool {
		if fd.Name() != "name" && !Reads(mask, string(fd.Name())) {
			drop = append(drop, fd)
		}
		return true
	})
	for _, fd := range drop {
		r.Clear(fd)
	}
}

// Unread lists the columns a read under mask leaves out: those of the fields
// in columns the mask does not read, less keep (the columns the read sorts
// and pages by, which it must have whatever the mask says). Columns no field
// owns -- keys, references to value objects, discriminators -- are always
// read.
func Unread(columns map[string][]string, mask []string, keep ...string) []string {
	if len(mask) == 0 {
		return nil
	}
	var out []string
	for field, cols := range columns {
		if Reads(mask, field) {
			continue
		}
		for _, c := range cols {
			if !slices.Contains(keep, c) {
				out = append(out, c)
			}
		}
	}
	slices.Sort(out)
	return out
}

// OrderColumns are the columns a list under spec and orderBy sorts by, the
// primary key included; nil when orderBy does not parse (the list rejects it).
func OrderColumns(spec filterx.Spec, orderBy string) []string {
	terms, err := filterx.OrderTerms(spec, orderBy)
	if err != nil {
		return nil
	}
	out := make([]string, 0, len(terms))
	for _, t := range terms {
		out = append(out, t.Column)
	}
	return out
}

// MapGormErr translates GORM's storage errors onto the repox sentinels,
// passing everything else (including sentinels already mapped inside a
// transaction) through unchanged.
func MapGormErr(err error) error {
	switch {
	case err == nil:
		return nil
	case errors.Is(err, gorm.ErrRecordNotFound):
		return ErrNotFound
	case errors.Is(err, gorm.ErrDuplicatedKey), sqlState(err) == "23505":
		return ErrAlreadyExists
	case sqlState(err) == "23503":
		// A foreign key: the row names a target that does not exist, or a
		// delete removes a row still named.
		return ForeignKeyError(err)
	case sqlState(err) == "23P01":
		// An exclusion constraint, (store.v1.table).no_overlap: the write
		// would overlap a row that already holds that time. Another writer
		// won the race; retrying against fresh state is meaningful.
		return ErrConflict
	case sqlState(err) == "40P01", sqlState(err) == "40001":
		// A deadlock or serialization failure: the database rolled the
		// transaction back to let a concurrent one through. Two writers
		// inserting conflicting rows under an exclusion constraint can each
		// wait on the other, so under contention this is the race being lost,
		// and like it, worth retrying.
		return ErrConflict
	default:
		return err
	}
}

// sqlState returns the SQLSTATE a driver error carries, or "". pgx's PgError
// exposes it as SQLState(); matching the method rather than the type keeps
// this package free of a driver import.
func sqlState(err error) string {
	var s interface{ SQLState() string }
	if errors.As(err, &s) {
		return s.SQLState()
	}
	return ""
}

// MapFilterxErr translates the filter/order engines' rejection onto
// ErrInvalidArgument, keeping the descriptive message and the engine's error
// (errors.Is(err, filterx.ErrUnsupported) still holds for what a backend
// cannot evaluate).
func MapFilterxErr(err error) error {
	if err == nil {
		return nil
	}
	if errors.Is(err, filterx.ErrInvalid) {
		return fmt.Errorf("%w: %w", ErrInvalidArgument, err)
	}
	return err
}

// SplitName splits an AIP resource name into its bare ids, validating the
// collection segments: SplitName("organisations/o1/members/m1",
// "organisations", "members") → ["o1", "m1"]. Any other shape is rejected
// with ErrInvalidArgument.
func SplitName(name string, collections ...string) ([]string, error) {
	parts := strings.Split(name, "/")
	if len(parts) != 2*len(collections) {
		return nil, fmt.Errorf("%w: malformed resource name %q", ErrInvalidArgument, name)
	}
	ids := make([]string, 0, len(collections))
	for i, c := range collections {
		if parts[2*i] != c || parts[2*i+1] == "" {
			return nil, fmt.Errorf("%w: malformed resource name %q", ErrInvalidArgument, name)
		}
		ids = append(ids, parts[2*i+1])
	}
	return ids, nil
}

// NamePattern turns a resource name whose ids may be AIP-159's "-" (any)
// into a LIKE pattern: each "-" id matches any id, every other character
// matches itself. wild is false, and pattern is name, when no id is "-".
func NamePattern(name string) (pattern string, wild bool) {
	parts := strings.Split(name, "/")
	for i := 1; i < len(parts); i += 2 {
		if parts[i] == "-" {
			wild = true
		}
	}
	if !wild {
		return name, false
	}
	esc := strings.NewReplacer(`\`, `\\`, "%", `\%`, "_", `\_`)
	for i, p := range parts {
		if i%2 == 1 && p == "-" {
			parts[i] = "%"
		} else {
			parts[i] = esc.Replace(p)
		}
	}
	return strings.Join(parts, "/"), true
}

// NameMatch is the SQL comparison (with its one placeholder) and argument
// that match a name column against name: equality, or LIKE when an id of
// name is "-" (see NamePattern).
func NameMatch(name string) (op, arg string) {
	if p, wild := NamePattern(name); wild {
		return "LIKE ?", p
	}
	return "= ?", name
}

// RowKey returns the surrogate key of the row of table (a quoted, qualified
// identifier) whose name is name, or fallback when there is none. A nested
// resource's row is keyed by a surrogate of its own rather than by its id, so
// a column pointing at it -- a nested child's ancestor column -- is filled
// from its name. The fallback, the bare id, lets the foreign key report a
// parent that does not exist, as it always has.
func RowKey(ctx context.Context, db *gorm.DB, table, name, fallback string) (string, error) {
	var keys []string
	if err := db.WithContext(ctx).Table(table).Where("name = ?", name).Limit(1).Pluck("id", &keys).Error; err != nil {
		return "", err
	}
	if len(keys) == 0 {
		return fallback, nil
	}
	return keys[0], nil
}

// LastSegment returns the final path component of a resource name — the bare
// id a reference column stores ("users/7" → "7").
func LastSegment(name string) string {
	if i := strings.LastIndex(name, "/"); i >= 0 {
		return name[i+1:]
	}
	return name
}

// InMask reports whether the mask selects field: an empty mask selects
// everything (full replace), otherwise an exact path match.
func InMask(paths []string, field string) bool {
	if len(paths) == 0 {
		return true
	}
	for _, p := range paths {
		if p == field {
			return true
		}
	}
	return false
}

// GroupTouched reports whether the mask touches field or any of its subpaths —
// message-typed fields are replaced wholesale when any part is selected.
func GroupTouched(paths []string, field string) bool {
	if len(paths) == 0 {
		return true
	}
	for _, p := range paths {
		if p == field || strings.HasPrefix(p, field+".") {
			return true
		}
	}
	return false
}

// CopyFields sets each top-level field of dst that paths names to src's
// value, clearing it where src has none: how UpdateWithOutputOnly carries
// the server-owned fields it names onto the merged record. A path into a
// message ("a.b") copies the whole field "a"; an unknown path is skipped.
func CopyFields(dst, src proto.Message, paths []string) {
	d, s := dst.ProtoReflect(), src.ProtoReflect()
	fields := d.Descriptor().Fields()
	for _, p := range paths {
		top, _, _ := strings.Cut(p, ".")
		fd := fields.ByName(protoreflect.Name(top))
		if fd == nil {
			continue
		}
		if s.Has(fd) {
			d.Set(fd, s.Get(fd))
		} else {
			d.Clear(fd)
		}
	}
}

// Ptr returns a pointer to v, for optional model columns.
func Ptr[T any](v T) *T { return &v }

// Deref returns *p, or T's zero value when p is nil.
func Deref[T any](p *T) T {
	if p == nil {
		var zero T
		return zero
	}
	return *p
}

// ulidMu guards the monotonic state NewULID carries between calls.
var (
	ulidMu       sync.Mutex
	ulidLastMs   uint64
	ulidLastRand [10]byte
)

// crockford is the ULID alphabet (Crockford base32, no I/L/O/U).
const crockford = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"

// ExpireAt is the expire_time a soft delete at at writes (AIP-164): at plus
// retention, or nil -- none -- when retention is not positive.
func ExpireAt(at time.Time, retention time.Duration) any {
	if retention <= 0 {
		return nil
	}
	return at.Add(retention)
}

// NewULID mints a 26-character ULID: 48 bits of millisecond timestamp and 80
// bits of crypto randomness, Crockford-base32 encoded, with no external
// dependency.
//
// Monotonic within the process, per the spec's monotonicity section: a ULID
// minted in the same millisecond as the previous one increments its random
// part instead of drawing a fresh one. Keys therefore sort in the order they
// were minted, which is what lets a repeated field stored as child rows be
// read back in the order it was written.
func NewULID() string {
	ulidMu.Lock()
	ms := uint64(time.Now().UnixMilli())
	if ms <= ulidLastMs {
		ms = ulidLastMs
		// Increment the 80-bit random part; on the (astronomically unlikely)
		// overflow, move to the next millisecond.
		i := 9
		for ; i >= 0; i-- {
			ulidLastRand[i]++
			if ulidLastRand[i] != 0 {
				break
			}
		}
		if i < 0 {
			ms++
			if _, err := rand.Read(ulidLastRand[:]); err != nil {
				ulidMu.Unlock()
				panic(fmt.Sprintf("repox: reading crypto/rand: %v", err))
			}
		}
	} else if _, err := rand.Read(ulidLastRand[:]); err != nil {
		ulidMu.Unlock()
		panic(fmt.Sprintf("repox: reading crypto/rand: %v", err))
	}
	ulidLastMs = ms
	var b [16]byte
	b[0], b[1], b[2], b[3], b[4], b[5] = byte(ms>>40), byte(ms>>32), byte(ms>>24), byte(ms>>16), byte(ms>>8), byte(ms)
	copy(b[6:], ulidLastRand[:])
	ulidMu.Unlock()

	// Encode the 128 bits as 26 base32 chars, most significant first: char c
	// covers bits [5c, 5c+5) of a virtual 130-bit value whose top two bits are
	// zero (so the first char is always 0-7, per the canonical spec).
	bitAt := func(i int) byte { // i in [0,130), 0 = most significant
		if i < 2 {
			return 0
		}
		i -= 2
		return (b[i/8] >> (7 - i%8)) & 1
	}
	var out [26]byte
	for c := 0; c < 26; c++ {
		var v byte
		for j := 0; j < 5; j++ {
			v = v<<1 | bitAt(c*5+j)
		}
		out[c] = crockford[v]
	}
	return string(out[:])
}
